#!/usr/bin/env python3
"""patch_dressing_cli.py -- the Layer 3 chain becomes runnable from a shell.

Lot 0.45.0 -> 0.46.0, Patina 0.20.0 -> 0.21.0, shape_metrics 0.2.1 -> 0.3.0.
Piece 4 of 5, first half.

WHY THIS IS THE NEXT THING AND NOT THE ADAPTER. level_factory adapters do not
import tools; they invoke COMMANDS (`plan_commands` returns a list of them, and
`fingerprint_inputs` hashes the files those commands read). Neither
`site_surfaces` nor `surface_dressing` had a command line, so there was nothing
for an adapter to plan. This is the missing half.

After this, the whole chain runs from a shell, which is exactly what a job
will do:

    tools/shape_metrics.py --dir <built dressing glbs> --json  > metrics.json
    lot/site_surfaces.py <site spec>       --out              > surfaces.json
    python -m patina.surface_dressing --surfaces --metrics --asset-sets --out

Verified end to end on the real `coldrun_pawn_job` spec with the real built
GLBs: 4 assets measured, 83 zones, 6 exclusions, 3,948 instances, 511,712
triangles, 4 unique meshes, audit clean, exit 0.

WHAT ELSE IS IN HERE, AND WHY IT IS NOT COSMETIC.

`shape_metrics` gains `plan_hull_area_m2` -- the plan hull in absolute square
metres, not only as the `plan_hull_fill` ratio. A dressing planner needs "how
much floor does one of these hide". Without the absolute figure it has to
reconstruct the area from the ratio and the bbox, and to do THAT it has to
decide which two of the three bbox axes are the ground plane -- the up-axis
question, asked again, in a consumer that had no reason to ask it. That is the
question this repo has got wrong more than once. The measurement belongs with
the measurer.

`catalogue_from_metrics` builds Patina's asset catalogue from that output:
measured heights, measured footprints, real triangle counts, off the built
GLBs. A genome declares a RANGE; the honesty rule is about the object that
actually exists.

An asset the `asset_sets` map does not name is SKIPPED, not guessed at. The
family decides which zones an asset may dress, and inventing one would put
litter on a gameplay path because nobody said not to.

`--strict` on `site_surfaces` turns findings into an exit code. Unreadable
building footprints stay a warn by default -- a raw site spec legitimately has
none -- but inside a pipeline that warn means every wall seam silently went
undressed, which is the failure mode the module exists to prevent.

The budget arguments accept `auto` and `none` as words as well as integers,
because an adapter passes strings and `int("auto")` is a stack trace at job
time rather than at configuration time.

VERIFIED: Lot 32 tests (29 + 3 CLI), Patina 39 (33 + 6), shape_metrics
selftest green with two new anchors (a unit cube's plan hull is 1 m2, a
unit-diameter sphere's is pi/4).

    python patch_dressing_cli.py --check
    python patch_dressing_cli.py --selftest
    python patch_dressing_cli.py
    python patch_dressing_cli.py --revert
"""
