def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "lot"))
                and os.path.isdir(os.path.join(d, "patina"))
                and os.path.isdir(os.path.join(d, "tools"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  python tools\\shape_metrics.py --selftest")
    print("  cd lot;    python -m pytest tests -q      # 32 in test_site_surfaces")
    print("  cd patina; python -m pytest tests -q      # 39 in test_surface_dressing")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_dressing_cli selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    import ast

    def src(rel):
        return base64.b64decode(PAYLOAD[rel]["b64"]).decode("utf-8")

    lot_src = src("lot/site_surfaces.py")
    pat_src = src("patina/patina/surface_dressing.py")
    met_src = src("tools/shape_metrics.py")

    # Both modules must be RUNNABLE, not merely importable -- that is the
    # whole patch. An adapter cannot plan a command that does not exist.
    for name, s in (("site_surfaces", lot_src),
                    ("surface_dressing", pat_src)):
        tree = ast.parse(s)
        if not any(isinstance(n, ast.FunctionDef) and n.name == "main"
                   for n in tree.body):
            fail(f"{name} has no main()")
        if '__name__ == "__main__"' not in s:
            fail(f"{name} has no __main__ entry point")
    print("  ok    both modules have main() and a __main__ entry point")

    # FALSIFICATION: the budget words must survive the shell. If `budget()`
    # only did int(), "auto" would raise at job time -- after the scheduler
    # has already decided the job is valid.
    if '"auto"' not in pat_src or '"none"' not in pat_src:
        fail("the CLI does not accept the words auto/none for its budgets")
    if "def budget(" not in pat_src:
        fail("no budget coercion; an adapter passes strings")
    print("  ok    budgets accept auto/none as words, not just integers")

    # The catalogue must come from measurements and must not invent a family.
    if "catalogue_from_metrics" not in pat_src:
        fail("no catalogue_from_metrics")
    if "plan_hull_area_m2" not in pat_src:
        fail("the catalogue does not read the measured footprint")
    if "plan_hull_area_m2" not in met_src:
        fail("shape_metrics does not report plan_hull_area_m2, so the "
             "consumer would have to reconstruct it from the bbox and guess "
             "the up axis")
    print("  ok    footprints are measured once, by the measurer")

    if 'VERSION = "0.3.0"' not in met_src:
        fail("shape_metrics VERSION was not bumped")

    lot_ver = src("lot/VERSION").strip()
    if lot_ver != "Lot 0.46.0":
        fail(f"lot VERSION payload is {lot_ver!r}")
    raw = base64.b64decode(PAYLOAD["patina/VERSION"]["b64"])
    if raw != b"Patina 0.21.0\r\n":
        fail(f"patina VERSION bytes are {raw!r}; that file is CRLF and must "
             "stay CRLF")
    if '__version__ = "0.21.0"' not in src("patina/patina/version.py"):
        fail("patina version.py and VERSION disagree")
    for rel, tag, keep in (("lot/CHANGELOG.md", "## [0.46.0]", "## [0.45.0]"),
                           ("patina/CHANGELOG.md", "## [0.21.0]",
                            "## [0.20.0]")):
        ch = src(rel)
        if tag not in ch or keep not in ch:
            fail(f"{rel} is not {tag} on top of {keep}")
    print("  ok    Lot 0.46.0, Patina 0.21.0, shape_metrics 0.3.0, histories "
          "kept")

    # The CLIs must be covered, or "it has a command line" is untested.
    for rel, needle in (("lot/tests/test_site_surfaces.py", "test_cli_"),
                        ("patina/tests/test_surface_dressing.py",
                         "test_cli_")):
        if needle not in src(rel):
            fail(f"{rel} has no CLI tests")
    print("  ok    both command lines are covered by tests")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
